#[test]
fn q_tags() {
    let mut options = WriterOptions::default();
    options.html_q_tags = true;
    options.html_math_method = HtmlMathMethod::MathJax(String::new());
    let doc = r###"{"pandoc-api-version": [1, 23, 1, 2], "meta": {}, "blocks": [{"t": "Para", "c": [{"t": "Quoted", "c": [{"t": "DoubleQuote"}, [{"t": "Str", "c": "q"}]]}, {"t": "Space"}, {"t": "Quoted", "c": [{"t": "SingleQuote"}, [{"t": "Str", "c": "s"}]]}, {"t": "Space"}, {"t": "Str", "c": "\u00e9\u2192"}, {"t": "Space"}, {"t": "Link", "c": [["", [], []], [{"t": "Str", "c": "me@x.org"}], ["mailto:me@x.org", ""]]}, {"t": "Space"}, {"t": "Link", "c": [["", [], []], [{"t": "Str", "c": "mail"}, {"t": "Space"}, {"t": "Str", "c": "me"}], ["mailto:me@x.org", ""]]}, {"t": "Space"}, {"t": "Math", "c": [{"t": "InlineMath"}, "a^2 + b"]}, {"t": "Space"}, {"t": "Math", "c": [{"t": "DisplayMath"}, "x<y"]}]}, {"t": "Para", "c": [{"t": "Span", "c": [["s", [], [["title", "\u00e9"]]], [{"t": "Str", "c": "\u00fc"}]]}]}]}"###;
    let expected = "<p><q>q</q> <q>s</q> é→ <a href=\"mailto:me@x.org\">me@x.org</a> <a\nhref=\"mailto:me@x.org\">mail me</a> <span class=\"math inline\">\\(a^2 +\nb\\)</span> <span class=\"math display\">\\[x&lt;y\\]</span></p>\n<p><span id=\"s\" title=\"é\">ü</span></p>\n";
    let warnings: &[&str] = &[];
    check(doc, &options, Version::Html5, expected, warnings);
}

