    options.reference_location = ReferenceLocation::EndOfSection;
    let doc = r###"{"pandoc-api-version": [1, 23, 1, 2], "meta": {}, "blocks": [{"t": "Header", "c": [1, ["", [], []], [{"t": "Note", "c": [{"t": "Para", "c": [{"t": "Str", "c": "n"}]}]}]]}, {"t": "Para", "c": []}]}"###;
